calls_detail.cmd:
gh api graphql -f query=
{
  search(query: "repo:vercel/next.js is:pr is:merged label:\"Pages Router\" merged:>=2025-01-01", type: ISSUE, first: 10) {
    issueCount
    nodes {
      ... on PullRequest {
        number
        title
        mergedAt
      }
    }
  }
}

gh api graphql -f query=
{
  search(query: "repo:vercel/next.js is:pr label:\"Pages Router\"", type: ISSUE, first: 5) {
    issueCount
    nodes {
      ... on PullRequest {
        number
        title
        state
        mergedAt
        labels(first: 5) { nodes { name } }
      }
    }
  }
}

gh api graphql -f query=
{
  search(query: "repo:vercel/next.js is:pr is:merged", type: ISSUE, first: 3) {
    issueCount
    nodes {
      ... on PullRequest { number title mergedAt }
    }
  }
}

gh api graphql -f query=
{
  repository(owner: "vercel", name: "next.js") {
    label(name: "Pages Router") {
      id
      name
      pullRequests(first: 10, states: MERGED, orderBy: {field: UPDATED_AT, direction: DESC}) {
        totalCount
        nodes {
          number
          title
          mergedAt
        }
      }
    }
  }
}

gh api graphql -f query=
{
  repository(owner: "vercel", name: "next.js") {
    label(name: "Pages Router") {
      id
      name
      issues(first: 3) {
        totalCount
      }
      pullRequests(first: 3, states: [OPEN, CLOSED, MERGED]) {
        totalCount
      }
    }
  }
}
